  tiles.forEach(([k, v, c], i) => {
    const x = 14 + i * (tw + 6)
    parts.push(`<rect class="k" x="${x}" y="52" width="${tw}" height="36" rx="9" opacity=".7"/>`)
    parts.push(svgText(x + tw / 2, 66, k, { cls: 's', size: 8.5, weight: 650, anchor: 'middle' }))
