      parts.push(`<rect x="${x.toFixed(1)}" y="98" width="${Math.max(1, w - 1.5).toFixed(1)}" height="8" rx="3" fill="${domainColor(g.domain)}"><title>${xml(`${g.domain}: ${g.crumbs.length}`)}</title></rect>`)
